# prints every panel's widgets, tray ids and the layout key
qdbus6 org.kde.plasmashell /PlasmaShell evaluateScript "for (const p of panels()) { p.currentConfigGroup=['General']; print('panel '+p.id+' isl='+p.readConfig('win12Island','')+' gone='+p.readConfig('win12Gone','')+' :: '+p.widgets().map(w=>w.id+':'+w.type.replace('org.kde.plasma.','')+'@'+w.index).join(' ')+'\n'); for (const w of p.widgets('org.kde.plasma.systemtray')) { w.currentConfigGroup=['General']; print(' tray '+w.id+' extra='+String(w.readConfig('extraItems','')).split(',').length+' keys='+w.configKeys.join(',')+'\n'); } }"
